using System.Linq;
using System.Windows;
using System.Windows.Media;

namespace Longyan;

/// The card's symbols, drawn for Windows: our own shapes with the same idea, size and weight as
/// the Mac card's, except the two note symbols, which are the Mac's outlines (Globe, Translate).
/// Each is a filled outline in the box (points) the Mac's symbol takes at the size the card uses
/// it, so it sits where the Mac's does. Made from circles, rounded boxes and strokes, widened
/// into outlines here, so one brush colours them and they scale with the card.
sealed record Icon(double Width, double Height, Geometry Geometry)
{
    /// The icon as a shape in `brush`, `Width` by `Height`.
    public System.Windows.Shapes.Path Shape(Brush brush) => new()
    {
        Data = Geometry, Fill = brush, Width = Width, Height = Height, Stretch = Stretch.None,
        RenderTransformOrigin = new Point(0.5, 0.5), SnapsToDevicePixels = false,
    };
}

static class Icons
{
    static Geometry G(string data) => Geometry.Parse(data);

    /// A line `width` wide along `data`, as an outline.
    static Geometry S(string data, double width, PenLineCap cap) =>
        Geometry.Parse(data).GetWidenedPathGeometry(new Pen(Brushes.Black, width) { StartLineCap = cap, EndLineCap = cap, LineJoin = PenLineJoin.Round }, 0.01, ToleranceType.Absolute);

    static Geometry U(params Geometry[] parts) =>
        parts.Skip(1).Aggregate(parts[0], (all, p) => Geometry.Combine(all, p, GeometryCombineMode.Union, null));

    /// A traced symbol: outline data (even-odd) in hundredths of the label's 11 pt, from the
    /// ink's top-left, so 100 units are 11 pt; the icon is its ink box.
    static Icon Traced(double width, double height, string data)
    {
        const double scale = 0.11;
        var g = Geometry.Parse("F0 " + data).CloneCurrentValue();
        g.Transform = new ScaleTransform(scale, scale);
        g.Freeze();
        return new(width * scale, height * scale, g);
    }

